DO $$ BEGIN CREATE TYPE "HardwareIssueType" AS ENUM ('PARTICIPANT', 'RENTAL', 'OTHER'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE "HardwareStatus" AS ENUM ('OPEN', 'MAIL_SEND', 'NOTIFIED', 'RETURNED', 'COMPLETED'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE "ObjectNumberType" AS ENUM ('SINGLE', 'RANGE', 'NONE'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
CREATE TABLE IF NOT EXISTS "HardwareIssue" (
  "id" UUID NOT NULL DEFAULT gen_random_uuid(), "eventId" UUID NULL, "recipientName" TEXT NOT NULL,
  "issueType" "HardwareIssueType" NOT NULL, "objectName" TEXT NOT NULL, "objectNumberType" "ObjectNumberType" NOT NULL,
  "objectNumberSingle" TEXT, "objectNumberPrefix" TEXT, "objectNumberFrom" INTEGER, "objectNumberTo" INTEGER,
  "objectNumberPadding" INTEGER, "quantity" INTEGER NOT NULL, "status" "HardwareStatus" NOT NULL DEFAULT 'OPEN',
  "email" TEXT, "phone" TEXT, "issuedAt" TIMESTAMP(3), "dueDate" TIMESTAMP(3), "returnedAt" TIMESTAMP(3), "note" TEXT,
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "HardwareIssue_pkey" PRIMARY KEY ("id")
);
CREATE INDEX IF NOT EXISTS "HardwareIssue_status_dueDate_idx" ON "HardwareIssue"("status", "dueDate");
